import { CellClassParams } from 'ag-grid-community';
import { cellClass } from 'components/Table/cellClass';
import { ColumnDefsConfig } from 'components/Table/Table';

const refreshStatusCellClass = (params: CellClassParams) => {
  const classes = [...cellClass(params)];
  const refreshStatus = params.data['refresh_status_config']?.tag;
  classes.push(`ag-cell-refresh-status-${refreshStatus?.value.toLowerCase()}`);
  return classes;
};

export const TABLE_CONFIGS_SOURCESTATUS: ColumnDefsConfig = {
  country: {
    maxWidth: 240,
    minWidth: 240,
  },
  refresh_status: {
    cellClass: (params) => refreshStatusCellClass(params),
    maxWidth: 240,
    minWidth: 240,
  },
};
